{
  "understanding": {
    "purpose": "2023년과 2024년의 주요 아파트 단지별 최저·최고 실거래가를 비교한다.",
    "reading": "단지명과 전용면적으로 행을 찾은 뒤, 같은 해의 최저·최고가와 두 해의 같은 지표를 가로로 비교한다.",
    "groups": [
      "단지명과 전용면적은 거래 대상을 식별한다.",
      "2023년의 최저·최고와 2024년의 최저·최고는 각각 한 해의 가격 범위를 이룬다.",
      "네 가격 열은 같은 역할을 하므로 비슷한 폭이 비교에 유리하다."
    ],
    "keep_intact": [
      "전용면적의 숫자와 단위",
      "가격의 숫자 묶음과 단위"
    ],
    "may_wrap": [
      "긴 단지명은 자연스럽게 줄바꿈할 수 있다.",
      "가격은 억 단위와 뒤따르는 금액 사이의 공백에서 줄바꿈할 수 있다.",
      "두 줄로 된 열 머리글과 본문의 여러 줄 행은 각 행 안에서 높이를 공유한다."
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [45, 66, 62, 62, 62, 62],
      "idea": "면적과 가격의 가장 긴 끊기지 않는 값을 유지하고 네 가격 열을 같게 두는 대신 단지명에 잦은 줄바꿈을 허용한다."
    },
    {
      "name": "B",
      "widths": [65, 66, 57, 57, 57, 57],
      "idea": "단지명에 더 많은 공간을 주고 네 가격 열을 균등하게 줄여 식별과 연도별 비교의 균형을 잡되 가격 숫자 묶음의 줄바꿈을 감수한다."
    },
    {
      "name": "C",
      "widths": [55, 66, 51, 51, 68, 68],
      "idea": "최근인 2024년 가격을 넓게 보여 주고 2023년 가격을 압축해 최근 수치의 세로 스캔을 우선한다."
    }
  ]
}
